const E = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const N = value => new Intl.NumberFormat('ar-SA-u-nu-latn', {maximumFractionDigits:0}).format(value);
const money = value => new Intl.NumberFormat('ar-SA-u-nu-latn', {minimumFractionDigits:2,maximumFractionDigits:2}).format(value);
const source = id => D.sources.find(s => s.id === id);
const safeUrl=url=>/^https?:\/\//i.test(String(url||''))?url:'#';
const link = (url, text, cls='') => `<a class="${cls}" href="${E(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${E(text)}</a>`;
const badge = (text, color='') => `<span class="tag ${color}">${E(text)}</span>`;
const stat = (label, value, detail, tone='') => `<div class="stat ${tone}"><span class="label">${E(label)}</span><strong>${E(value)}</strong><span class="detail">${E(detail)}</span></div>`;
const day = value => {const raw=String(value||'').trim().replace(/[٠-٩]/g,c=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(c)));const iso=raw.match(/^(\d{4})-(\d{2})-(\d{2})$/),parts=raw.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{4})$/);const date=iso?raw:parts?parts[3]+'-'+parts[2].padStart(2,'0')+'-'+parts[1].padStart(2,'0'):null;if(!date)return null;const parsed=new Date(date+'T12:00:00Z');return Number.isFinite(parsed.getTime())&&parsed.toISOString().slice(0,10)===date?date:null;};
const overdue = task => Boolean(day(task.due) && day(task.due)<D.snapshotDate && task.status!=='تم الإنجاز');
const urgent = task => String(task.priority||'').includes('عاجل');
const searchKey=value=>String(value||'').normalize('NFKC').replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').replace(/[\u064B-\u065F\u0640]/g,'').toLowerCase().trim();
const ownerKey=value=>String(value||'').trim()==='هانى'?'هاني':String(value||'').trim();
const urgentTasks = D.tasks.filter(t=>urgent(t)&&t.status!=='تم الإنجاز').sort((a,b)=>Number(b.priority==='عاجل جدا')-Number(a.priority==='عاجل جدا'));
