const shortlisted = D.hiring.filter(recommended);
const views={overview:['نظرة عامة','المهام المباشرة، التوظيف، المبيعات وقنوات الفريق.'],tasks:['المهام المباشرة','التكليفات الواردة في شيت المتابعة، مع آخر ملاحظة مسجلة.'],hiring:['متابعة التوظيف','محاسب · صانعة محتوى · مبيعات الرياض · مبيعات جدة · مبيعات سيدات · جرافيك ديزاين.'],sales:['مبيعات B2B','مبيعات مناديب إيميز · ملخص السجلات المقروءة.'],archive:['أرشيف الإنجاز','سجلات المهام المكتملة، مع الاحتفاظ بالتكرارات كما وردت في المصدر.'],sources:['قنوات ومصادر المتابعة','10 مصادر تجمع التكليفات والتقارير وقنوات الفريق.']};
