let b2cPeriod='month';
function renderB2C(){
 const b=D.b2c;if(!b){content.innerHTML='<p>لم تصل تقارير سلة بعد.</p>';return;}
 const labels={today:'اليوم',yesterday:'أمس',month:'الشهر الحالي'};
 const r=b.reports[b2cPeriod]?.rows?.[0];
 const val=(key,currency=false)=>r&&Number.isFinite(r[key])?(currency?money(r[key]):N(r[key])):'غير متاح';
 const rows=b.reports.daily?.rows||[];
 const max=Math.max(1,...rows.map(x=>Number(x.order_count)||0));
 content.innerHTML=`<p class="scope-note">${E(b.store.name)} · آخر جلب: ${E(new Date(b.checkedAt).toLocaleString('ar-SA',{timeZone:'Asia/Riyadh'}))} بتوقيت الرياض · اليوم الجاري غير مكتمل</p><div class="sale-tabs">${Object.entries(labels).map(([k,v])=>`<button class="button" data-b2c-period="${k}" aria-pressed="${b2cPeriod===k}">${v}</button>`).join('')}</div><div class="stats">${stat('إجمالي المبيعات',val('sales.total_sales',true),'ريال · كما ورد في تقرير سلة')}${stat('الطلبات',val('sales.orders_count'),labels[b2cPeriod])}${stat('متوسط قيمة الطلب',val('avg-cart-price',true),'ريال · حسب تعريف سلة')}${stat('العملاء',val('customer-count'),labels[b2cPeriod])}${stat('المرتجعات',val('order-returned-count'),'عدد وفق التقرير')}</div>${renderB2CFinance(r,labels[b2cPeriod])}${Object.keys(b.errors||{}).length?'<p class="notice warning">تعذر جلب بعض التقارير؛ القيم غير المتاحة لا تعني صفرًا.</p>':''}<p class="scope-note">تاريخ آخر نجاح للتقرير المختار: ${E(b.reportCheckedAt?.[b2cPeriod]||b.checkedAt)} · تقرير الطلبات اليومية: ${E(b.reportCheckedAt?.daily||b.checkedAt)}.</p><p class="notice">قيمة الطلبات اليومية ومتوسط الطلب قد يختلفان عن إجمالي المبيعات بسبب تعريفات تقارير سلة والخصومات والتقريب؛ لا تُعرض هذه القيم باعتبارها صافي ربح أو تحصيل بنكي.</p><section class="panel"><div class="panelhead"><h2>اتجاه الطلبات اليومية</h2></div><div class="panelbody"><div style="display:flex;align-items:end;gap:4px;height:150px;direction:ltr" aria-label="عدد الطلبات حسب التاريخ">${rows.map(x=>`<div title="${E(x.order_date)}: ${N(x.order_count)} طلب" style="flex:1;background:var(--teal);height:${Math.max(2,Number(x.order_count)/max*140)}px"><span class="scope-note" style="display:none">${N(x.order_count)}</span></div>`).join('')}</div><p class="scope-note">${E(rows[0]?.order_date||'')} ← ${E(rows.at(-1)?.order_date||'')} · التفاصيل في الجدول التالي</p></div></section><section class="panel"><div class="panelhead"><h2>التقرير اليومي للطلبات</h2>${link('https://s.salla.sa/','فتح سلة ↗','button')}</div><div class="tablewrap"><table><thead><tr><th>التاريخ</th><th>الطلبات</th><th>العملاء</th><th>قيمة الطلبات (ريال)</th></tr></thead><tbody>${[...rows].reverse().map(x=>`<tr><td>${E(x.order_date)}</td><td>${N(x.order_count)}</td><td>${N(x.customer_count)}</td><td>${money(x.order_total_sum)}</td></tr>`).join('')}</tbody></table></div></section><p class="scope-note">${E(b.dailyNote||'')} لا تُفسّر الأيام الغائبة كأيام بلا مبيعات.</p>`;
 const sc=D.sallaComplaints||{};
 const count=v=>Number.isFinite(v)?N(v):'غير متاح';
 content.insertAdjacentHTML('afterbegin',`<section class="panel" id="salla-complaints"><div class="panelhead"><h2>شكاوى سلة</h2></div><div class="panelbody"><p class="notice ${sc.status==='error'?'warning':''}" role="status">${E(sc.error||'المتابعة اليومية للشكاوى وتغير حالتها')}</p><div class="stats">${stat('الشكاوى المفتوحة',count(sc.open),'وفق نطاق المصدر')}${stat('الشكاوى المغلقة',count(sc.closed),'حالة الإغلاق كما تظهر في سلة')}</div><p>${E(sc.scope||'نطاق البيانات لم يُتحقق بعد.')}</p><p class="scope-note">آخر محاولة: ${E(sc.checkedAt||'لم تتم')} · آخر نجاح: ${E(sc.lastSuccessAt||'لا توجد قراءة ناجحة بعد')} · متابعة يومية الساعة 08:00 بتوقيت الرياض.</p><h3>تنبيهات الشكاوى</h3>${(sc.events||[]).length?'<ul>'+sc.events.map(x=>'<li>'+E(x.date)+' — '+E(x.message)+'</li>').join('')+'</ul>':'<p>لا توجد تنبيهات مؤكدة مسجلة حتى الآن؛ هذا لا يعني عدم وجود شكاوى.</p>'}</div></section>`);
 content.querySelectorAll('[data-b2c-period]').forEach(btn=>btn.addEventListener('click',()=>{b2cPeriod=btn.dataset.b2cPeriod;renderB2C();}));
}

let socialPlatform='tiktok';
function renderSocial(){
 const platforms=[...(D.social?.platforms||[]),...(D.social?.storeReview?[{id:'store',name:'المتجر الإلكتروني'}]:[])];if(socialPlatform==='store'){renderStoreReview(platforms);return;}const p=platforms.find(x=>x.id===socialPlatform)||platforms[0];
 if(!p){content.innerHTML='<p>لم تصل بيانات الحسابات بعد.</p>';return;}
 content.innerHTML=`<div class="sale-tabs">${platforms.map(x=>`<button class="button" data-social-platform="${E(x.id)}" aria-pressed="${x.id===p.id}">${E(x.name)}</button>`).join('')}</div><section class="panel"><div class="panelhead"><h2>${E(p.name)}</h2>${p.url?link(p.url,'فتح الحساب ↗','button'):badge('بانتظار رابط الحساب','amber')}</div><div class="panelbody"><p class="notice">${E(p.accessNote||'بانتظار رابط الحساب.')} لم يبدأ جلب إحصاءات الأداء اليومية بعد؛ يلزم الوصول إلى إحصاءات الحساب.</p><p class="scope-note">آخر قراءة لإحصاءات الأداء: ${p.lastSuccessAt?E(p.lastSuccessAt):'لم تتم بعد'}</p>${p.publicCheckedAt?`<p class="scope-note">فحص الصفحة العامة: ${E(p.publicCheckedAt.slice(0,10))}</p>`:''}${p.publicMetrics?.length?`<div class="stats">${p.publicMetrics.map(m=>stat(m.label,E(m.value),'لقطة عامة تراكمية')).join('')}</div>`:''}</div></section><div class="stats">${stat('الوصول والمشاهدات','—','بانتظار إحصاءات المنصة')}${stat('التفاعل','—','إعجابات وتعليقات ومشاركات وحفظ بحسب المنصة')}${stat('النقرات إلى المتجر','—','بانتظار بيانات الروابط والحملات')}${stat('الطلبات المنسوبة','—','تحتاج ربط الإحالة أو الحملات بسلة')}</div>${renderSocialPosts(p)}<section class="panel"><div class="panelhead"><h2>ملخص رصد المحتوى</h2></div><div class="panelbody"><p>آخر فحص: ${E(p.contentCheckedAt?.slice(0,10)||'غير متاح')} · ${(p.contentChecks||[]).at(-1)?.newCount??'غير متاح'} روابط لم تُرصد في الفحص السابق.</p><p>${E(p.contentNote||'لم تتوفر قراءة بعد')}</p><p class="scope-note">هذا ملخص للمحتوى العام؛ تقارير الوصول والتحويل التفصيلية لم تُستورد بعد.</p><ul class="agenda"><li>أداء المحتوى المنشور ومقارنته بالفترات السابقة.</li><li>تغير المتابعين والوصول والمشاهدات والتفاعل وفق ما تتيحه المنصة.</li><li>الإنفاق والنتائج وتكلفة النتيجة عند توفر بيانات الإعلانات.</li><li>ملاحظات اليوم والإجراءات المقترحة، مع توضيح مصدر البيانات وتاريخها.</li></ul></div></section><section class="panel"><div class="panelhead"><h2>دراسة سلوك العميل</h2></div><div class="panelbody"><h3>تفاعل الجمهور</h3><p>مقارنة أنواع المحتوى وموضوعاته، وأوقات التفاعل، والاهتمام بالمنتجات، والأسئلة والاعتراضات المتكررة في التعليقات المتاحة.</p><h3>الانتقال إلى الشراء</h3><p>ربط الزيارات والحملات بالطلبات عند توفر بيانات الإحالة في سلة. نعرض فترة الإسناد وطريقته؛ ولا نعتبر التفاعل وحده دليلًا على الشراء.</p><h3>النتائج والتوصيات</h3><p>سيُفصل بين الأرقام المرصودة، والاستنتاجات المدعومة، والفرضيات التي تحتاج اختبارًا. التحليل سيكون على مستوى الجمهور والمجموعات دون إنشاء ملفات شخصية للعملاء.</p><p class="scope-note">لا توجد استنتاجات سلوكية فعلية قبل جمع بيانات كافية. الروابط العامة لا توفر وحدها الوصول والنقرات والمبيعات أو جميع بيانات الجمهور.</p></div></section>`;
 content.querySelectorAll('[data-social-platform]').forEach(b=>b.addEventListener('click',()=>{socialPlatform=b.dataset.socialPlatform;renderSocial();}));
}

